{%- set bats = states.sensor | selectattr('entity_id', 'match', 'sensor.marstekvenus_[0-9]+_battery_soc$') | map(attribute='entity_id') | map('regex_replace', '[^0-9]', '') | map('int') | sort | list -%}
{%- set tol = states('number.marstek_tolerance_w') | float(40) -%}
{%- set min_soc = states('number.marstek_soc_safety_min_soc') | int(11) -%}
{%- set full_days = states('number.marstek_full_charge_interval_days') | int(10) -%}
{%- set now_ts = now().timestamp() -%}
{%- set ns = namespace(socs=[], newest=0, pc=0, pd=0) -%}
{%- for n in bats -%}
{%- set s = states('sensor.marstekvenus_' ~ n ~ '_battery_soc') | float(-1) -%}
{%- if s >= 0 %}{% set ns.socs = ns.socs + [s] %}{% endif -%}
{%- endfor -%}
{%- set avg = (ns.socs | sum / ns.socs | count) if ns.socs else 0 -%}
| | Batterie | Letzter Kontakt | Macht gerade | SoC | Temp. max | Letzte Vollladung | Auffälligkeiten |
|:-:|---|---|---|--:|--:|---|---|
{% for n in bats -%}
{%- set p = 'sensor.marstekvenus_' ~ n ~ '_' -%}
{%- set ents = states.sensor | selectattr('entity_id','match','sensor.marstekvenus_' ~ n ~ '_') | rejectattr('state','in',['unavailable','unknown']) | list -%}
{%- set last = (ents | map(attribute='last_updated') | map('as_timestamp') | max) if ents else 0 -%}
{%- if last > ns.newest %}{% set ns.newest = last %}{% endif -%}
{%- set age = (now_ts - last) | int if last else -1 -%}
{%- set soc = states(p ~ 'battery_soc') | float(-1) -%}
{%- set ac = states(p ~ 'ac_power') | float(0) -%}
{%- set tmax = [states(p ~ 'temp_internal') | float(0), states(p ~ 'temp_mos1') | float(0), states(p ~ 'temp_mos2') | float(0)] | max -%}
{%- set bms = 'sensor.bms_battery' ~ n ~ '_phase' -%}
{%- set phase = states(bms) -%}
{%- set lf = state_attr(bms, 'last_full') -%}
{%- set lf_ts = as_timestamp(lf, 0) if lf not in [none, 'nie', ''] else 0 -%}
{%- set lf_days = ((now_ts - lf_ts) / 86400) if lf_ts else -1 -%}
{%- set comm = states('sensor.pv_battery' ~ n ~ '_comm_mode') -%}
{%- set prim = state_attr('sensor.pv_battery' ~ n ~ '_comm_mode', 'primary_mode') -%}
{%- set i = namespace(l=[], lvl=0) -%}
{%- if age < 0 %}{% set i.l = i.l + ['keine Daten'] %}{% set i.lvl = 2 -%}
{%- elif age > 900 %}{% set i.l = i.l + ['seit ' ~ (age / 60) | int ~ ' min nicht erreichbar'] %}{% set i.lvl = 2 -%}
{%- elif age > 300 %}{% set i.l = i.l + ['Daten verzögert (' ~ (age / 60) | int ~ ' min)'] %}{% set i.lvl = [i.lvl, 1] | max %}{% endif -%}
{%- if soc < 0 %}{% set i.l = i.l + ['SoC fehlt'] %}{% set i.lvl = 2 -%}
{%- elif soc <= min_soc %}{% set i.l = i.l + ['SoC am Minimum'] %}{% set i.lvl = [i.lvl, 1] | max -%}
{%- elif ns.socs | count > 1 and (soc - avg) | abs > 15 %}{% set i.l = i.l + ['SoC weicht ' ~ (soc - avg) | round(0) | int ~ ' % vom Schnitt ab'] %}{% set i.lvl = [i.lvl, 1] | max %}{% endif -%}
{%- if tmax >= 55 %}{% set i.l = i.l + ['Temperatur hoch (' ~ tmax ~ ' °C)'] %}{% set i.lvl = 2 -%}
{%- elif tmax >= 45 %}{% set i.l = i.l + ['Temperatur erhöht'] %}{% set i.lvl = [i.lvl, 1] | max %}{% endif -%}
{%- if comm in ['unavailable', 'unknown'] %}{% set i.l = i.l + ['Protokoll-Status fehlt'] %}{% set i.lvl = [i.lvl, 1] | max -%}
{%- elif prim and comm | lower != prim | lower %}{% set i.l = i.l + ['Fallback aktiv: ' ~ comm ~ ' statt ' ~ prim] %}{% set i.lvl = [i.lvl, 1] | max %}{% endif -%}
{%- if lf_days < 0 %}{% set i.l = i.l + ['keine Vollladung bekannt'] %}{% set i.lvl = [i.lvl, 1] | max -%}
{%- elif lf_days > full_days + 2 %}{% set i.l = i.l + ['Vollladung überfällig'] %}{% set i.lvl = [i.lvl, 1] | max %}{% endif -%}
{%- if age < 0 or age > 900 %}{% set act = '—' -%}
{%- elif phase == 'charging' %}{% set act = '🔋 BMS-Vollladung (' ~ ac | abs | int ~ ' W)' -%}
{%- elif phase == 'holding' %}{% set act = '🔋 BMS hält voll' -%}
{%- elif phase == 'cooldown' %}{% set act = '🧊 BMS-Pause' -%}
{%- elif ac < -tol %}{% set act = '⬆️ lädt ' ~ ac | abs | int ~ ' W' -%}
{%- elif ac > tol %}{% set act = '⬇️ entlädt ' ~ ac | int ~ ' W' -%}
{%- else %}{% set act = '⏸️ Standby' %}{% endif -%}
{%- if ac < -tol %}{% set ns.pc = ns.pc + ac | abs %}{% elif ac > tol %}{% set ns.pd = ns.pd + ac %}{% endif -%}
| {{ ['🟢','🟡','🔴'][i.lvl] }} | **Venus {{ n }}** · {{ comm }} | {% if age < 0 %}nie{% elif age < 120 %}vor {{ age }} s{% elif age < 7200 %}vor {{ (age / 60) | int }} min{% else %}vor {{ (age / 3600) | round(1) }} h{% endif %} | {{ act }} | {{ soc | int if soc >= 0 else '–' }} % | {{ tmax | round(1) }} °C | {% if lf_days < 0 %}–{% elif lf_days < 1 %}heute/gestern{% else %}vor {{ lf_days | round(0) | int }} Tagen{% endif %} | {{ i.l | join(', ') if i.l else 'keine' }} |
{% endfor %}
{%- set sys_age = (now_ts - ns.newest) | int if ns.newest else -1 %}
{%- set grid = '__GRID_SENSOR__' %}
{%- set g_age = (now_ts - as_timestamp(states[grid].last_updated)) | int if states[grid] else -1 %}

**Gesamt:** {% if ns.pc > 0 %}lädt {{ ns.pc | int }} W{% endif %}{% if ns.pc > 0 and ns.pd > 0 %} · {% endif %}{% if ns.pd > 0 %}entlädt {{ ns.pd | int }} W{% endif %}{% if ns.pc == 0 and ns.pd == 0 %}Standby{% endif %} · Ø SoC {{ avg | round(0) | int }} %  
{% if sys_age < 0 or sys_age > 300 %}🔴 **AppDaemon-Script liefert keine Daten** (seit {{ (sys_age / 60) | int }} min) – AppDaemon-Add-on/Log prüfen{% else %}🟢 Script aktiv (letzte Daten vor {{ sys_age }} s){% endif %} · {% if g_age < 0 or states(grid) in ['unavailable','unknown'] %}🔴 Netz-Zähler nicht verfügbar{% elif g_age > 120 %}🟡 Netz-Zähler seit {{ (g_age / 60) | int }} min ohne neuen Wert{% else %}🟢 Netz-Zähler ok ({{ states(grid) | int }} W){% endif %}

<sub>Grenzen: Kontakt 🟡 > 5 min, 🔴 > 15 min · Temp. 🟡 ≥ 45 °C, 🔴 ≥ 55 °C · Vollladung alle {{ full_days }} Tage (+2 Tage Toleranz) · Min-SoC {{ min_soc }} %</sub>
